public static partial class Art {
 public static SolidColorBrush Brush(uint rgb,double alpha=1){var b=new SolidColorBrush(Color.FromArgb((byte)Math.Clamp(alpha*255,0,255),(byte)(rgb>>16),(byte)(rgb>>8),(byte)rgb));b.Freeze();return b;}
 public static readonly Brush Forest=Brush(0x233B32),Cream=Brush(0xF7F4EB),Muted=Brush(0x819087);
 public static ImageSource Roach=Load("roach"),Ant=Load("ant");
 private static ImageSource Load(string name){var image=new BitmapImage(new Uri("pack://application:,,,/Assets/"+name+".png"));var source=new FormatConvertedBitmap(image,PixelFormats.Bgra32,null,0);int width=source.PixelWidth,height=source.PixelHeight;var pixels=new byte[width*height*4];source.CopyPixels(pixels,width*4,0);int lx=width,ty=height,rx=0,by=0;for(int y=0;y<height;y++)for(int x=0;x<width;x++)if(pixels[(y*width+x)*4+3]>16){lx=Math.Min(lx,x);rx=Math.Max(rx,x);ty=Math.Min(ty,y);by=Math.Max(by,y);}if(lx>=rx||ty>=by)throw new InvalidOperationException("Empty texture");var cropped=new CroppedBitmap(source,new Int32Rect(lx,ty,rx-lx+1,by-ty+1));cropped.Freeze();return cropped;}
 private sealed class Scope:IDisposable {private DrawingContext c;private int n;public Scope(DrawingContext context,int count){c=context;n=count;}public void Dispose(){for(int i=0;i<n;i++)c.Pop();}}
 public static IDisposable Transform(DrawingContext c,double x=0,double y=0,double angle=0,double sx=1,double sy=1,double opacity=1){c.PushTransform(new TranslateTransform(x,y));c.PushTransform(new RotateTransform(angle*180/Math.PI));c.PushTransform(new ScaleTransform(sx,sy));c.PushOpacity(Math.Clamp(opacity,0,1));return new Scope(c,4);}
 public static void Oval(DrawingContext c,double x,double y,double width,double height,Brush fill,Pen? pen=null)=>c.DrawEllipse(fill,pen,new Point(x+width/2,y+height/2),Math.Max(.01,width/2),Math.Max(.01,height/2));
 public static void Line(DrawingContext c,Brush color,double width,params V[] points){var pen=new Pen(color,width){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round,LineJoin=PenLineJoin.Round};for(int i=1;i<points.Length;i++)c.DrawLine(pen,new Point(points[i-1].X,points[i-1].Y),new Point(points[i].X,points[i].Y));}
 public static void Text(DrawingContext c,string text,double x,double y,double size,Brush? color=null)=>c.DrawText(new FormattedText(text,CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),size,color??Forest,1),new Point(x,y));
 private static Geometry Polygon(params V[] points){var path=new StreamGeometry();using(var p=path.Open()){p.BeginFigure(new Point(points[0].X,points[0].Y),true,true);foreach(var v in points.Skip(1))p.LineTo(new Point(v.X,v.Y),true,false);}path.Freeze();return path;}
 private static Brush Gradient(uint light,uint dark)=>new LinearGradientBrush(((SolidColorBrush)Brush(light)).Color,((SolidColorBrush)Brush(dark)).Color,new Point(.2,0),new Point(.8,1));
 public static void Bug(DrawingContext c,Bug b,double phase,bool dead=false){bool roach=b.Species==Species.Roach;double size=roach?1.25:.65;using var scope=Transform(c,sx:size,sy:size);if(!roach&&b.Morph==0){for(int n=0;n<6;n++)Oval(c,-14+n*4,-4+Math.Sin(phase*.5+n*.35),7,8,Gradient(0xE2D7BA,0x9D9278));return;}
  for(int side=-1;side<=1;side+=2)for(int n=0;n<3;n++){double root=roach?15-n*10:2-n*2.2,swing=Math.Sin(phase+n*2.1+(side>0?0:Math.PI))*(roach?3.7:3),kneeX=root+(1-n)*(roach?8:7)+swing,kneeY=side*(roach?13+n*1.5:9+n),footX=root+(1-n)*(roach?18:15)-swing,footY=side*(roach?23+n*1.4:17-n);var leg=Brush(roach?0x61351Du:0x302820u);Line(c,leg,roach?2:1,new V(root,side*(roach?5:2)),new V(kneeX,kneeY),new V(footX,footY));Line(c,Brush(roach?0xB47338u:0x8A7763u),roach?.7:.3,new V(root,side*3),new V(kneeX,kneeY));if(roach)for(int j=1;j<=5;j++){double t=j/6d,x=kneeX+(footX-kneeX)*t,y=kneeY+(footY-kneeY)*t;Line(c,Brush(0x34291C),.4,new V(x,y),new V(x-2,y+side*2.4));}Line(c,leg,.5,new V(footX,footY),new V(footX-3,footY+side*2));}
  if(roach&&!dead&&b.Flight!=null)Wings(c,phase,b.Flight.Open);
  var body=roach?Roach:Ant;double bw=roach?52:40,bh=bw*body.Height/body.Width;c.DrawImage(body,new Rect(-bw/2,-bh/2,bw,bh));if(roach&&b.Morph<2){Oval(c,-26,-9,43,18,Gradient(b.Morph==0?0xB88A5Du:0x9C552Eu,0x482919));for(int n=0;n<6;n++)Line(c,Brush(0xD0A06B,.6),.7,new V(-22+n*6,-7),new V(-21+n*6,7));}
  foreach(int side in new[]{-1,1}){double sway=Math.Sin(phase*.31+side)*(roach?5:1.4);if(roach){var points=new List<V>();for(int n=0;n<=18;n++){double t=n/18d;points.Add(new V(24+43*t+sway*t*t,side*(3+8*t+(15+sway)*t*t)));}Line(c,Brush(0x70452B),.55,points.ToArray());}else Line(c,Brush(0x554330),.6,new V(13,side*3),new V(23,side*(8+sway)),new V(31+sway,side*5));}
 }
 public static void Egg(DrawingContext c,Species s){if(s==Species.Roach){Oval(c,-4,-2,8,4,Gradient(0xA65A2B,0x58311F));for(int n=0;n<4;n++)Line(c,Brush(0xC49156),.35,new V(n*1.5-2,-1.3),new V(n*1.5-2,1.3));}else Oval(c,-1.6,-.85,3.2,1.7,Gradient(0xF2EBCE,0xB5AB8C));}
 public static void Food(DrawingContext c,Snack kind,int remaining,int original,double scale=1){using var scope=Transform(c,sx:scale,sy:scale);double eaten=Math.Clamp(1-remaining/(double)Math.Max(1,original),0,1);Geometry shape=kind==Snack.Cookie?new EllipseGeometry(new Point(0,0),18,18):new RectangleGeometry(new Rect(-24,-24,48,50));for(int n=0;n<7;n++){double t=Math.Clamp(eaten*7-n,0,1);if(t<=0)continue;double a=n*Math.PI*2/7;shape=new CombinedGeometry(GeometryCombineMode.Exclude,shape,new EllipseGeometry(new Point(Math.Cos(a)*20,Math.Sin(a)*20),16*Math.Sqrt(t),16*Math.Sqrt(t)));}c.PushClip(shape);
  if(kind==Snack.Cookie){Oval(c,-18,-18,36,36,Gradient(0xEDD090,0xBD8A45));foreach(var v in new[]{new V(-8,-4),new V(4,-10),new V(9,4),new V(-4,9),V.Zero})Oval(c,v.X-1.6,v.Y-1.6,3.2,3.2,Brush(0x735034));}
  else if(kind==Snack.Pizza){c.DrawGeometry(Brush(0xE9B64E),null,Polygon(new V(-23,-22),new V(23,-13),new V(-17,24)));Line(c,Brush(0xCB8837),5,new V(-23,-22),new V(23,-13));foreach(var v in new[]{new V(-9,-10),new V(4,-6),new V(-12,7)})Oval(c,v.X-4,v.Y-4,8,8,Brush(0xAA4F31));}
  else if(kind==Snack.Cake||kind==Snack.Banquet){c.DrawRoundedRectangle(Gradient(0xD9A365,0xAC693A),null,new Rect(-22,-14,44,35),3,3);c.DrawRectangle(Brush(0xF6E7BC),null,new Rect(-21,2,42,5));c.DrawRoundedRectangle(Brush(0xF3DCCC),null,new Rect(-23,-21,46,14),6,6);Oval(c,-5,-26,10,10,Brush(0xBD4B38));}
  else if(kind==Snack.Cheese){c.DrawGeometry(Brush(0xE9B744),null,Polygon(new V(-22,18),new V(-16,-20),new V(24,12)));foreach(var v in new[]{new V(-9,8),new V(-10,-8),new V(5,7)})Oval(c,v.X-3,v.Y-2,6,5,Brush(0xC78E28));}
  else {var strawberry=new StreamGeometry();using(var p=strawberry.Open()){p.BeginFigure(new Point(0,23),true,true);p.BezierTo(new Point(-30,-3),new Point(-21,-24),new Point(0,-17),true,false);p.BezierTo(new Point(21,-24),new Point(30,-3),new Point(0,23),true,false);}c.DrawGeometry(Gradient(0xDF6650,0xA82E29),null,strawberry);for(int n=0;n<12;n++)Oval(c,(n%3-1)*8,(n/3)*8-12,1.8,2.6,Brush(0xF3C57A));Line(c,Brush(0x5C7940),2,new V(-10,-20),new V(0,-14),new V(10,-20));}c.Pop();}
 public static void Slipper(DrawingContext c,double scale=1){using var t=Transform(c,angle:-.4,sx:scale,sy:scale);c.DrawRoundedRectangle(Brush(0xB56D42),null,new Rect(-18,-34,36,70),15,15);c.DrawRoundedRectangle(Brush(0xEAA679),null,new Rect(-16,-33,32,65),14,14);c.DrawRoundedRectangle(Brush(0xF5C39E),null,new Rect(-15,-21,30,26),9,9);for(int n=0;n<4;n++)Line(c,Brush(0xC9895E),1,new V(-11,14+n*4),new V(11,14+n*4));}
 public static void Broom(DrawingContext c,double angle=0){using var t=Transform(c,angle:angle);Line(c,Brush(0x896340),5,new V(0,-44),new V(-2,13));c.DrawRoundedRectangle(Brush(0x61775D),null,new Rect(-16,8,29,7),2,2);for(int n=0;n<18;n++)Line(c,Brush(n%3==0?0xB38A42u:0xD5B968u),1.3,new V(-14+n*1.55,14),new V(-22+n*2.4,42+Math.Abs(n-9)*.25));}
 public static void Outsider(DrawingContext c,Invader v){using var t=Transform(c,angle:v.Angle,sy:v.Dead?.5:1,opacity:v.Dead?.55:1);if(v.Kind==InvaderKind.Centipede||v.Kind==InvaderKind.Snake||v.Kind==InvaderKind.Rat){VisitorBody(c,v);return;}int count=v.Kind==InvaderKind.Spider?4:3;foreach(int side in new[]{-1,1})for(int n=0;n<count;n++){double x=n*12-18,sway=Math.Sin(v.Phase+n*1.8+side)*6;Line(c,Brush(v.Kind==InvaderKind.Spider?0x46372Bu:0x3E4B31u),v.Kind==InvaderKind.Spider?3:2,new V(x,side*5),new V(x+(n-1)*12+sway,side*26),new V(x+(n-1)*24-sway,side*45));}if(v.Kind==InvaderKind.Spider){Oval(c,-34,-18,42,36,Gradient(0x80694F,0x2B231D));Oval(c,-5,-13,30,26,Gradient(0x987857,0x37291E));}else{Oval(c,-36,-24,65,48,Gradient(0x9EAA60,0x29412C));Line(c,Brush(0x263828),2,new V(-30,0),new V(18,0));}foreach(int side in new[]{-1,1})Line(c,Brush(0x89714C),2,new V(22,side*5),new V(33,side*9),new V(30,0));}
 public static void Juice(DrawingContext c,Splat s,bool flying=false,double alpha=1){using var t=Transform(c,s.P.X,s.P.Y,s.Angle,opacity:alpha);double r=s.Radius;if(!flying){double spread=.28+.72*Math.Min(1,s.Age/.23);using var scale=Transform(c,sx:spread,sy:spread);var points=new V[28];for(int n=0;n<28;n++){double a=n*Math.PI*2/28,wobble=.92+Math.Sin(n*2.3+s.BugId%17)*.14;points[n]=new V(Math.Cos(a)*r*1.75*wobble,Math.Sin(a)*r*.76*wobble);}var pool=new StreamGeometry();using(var curve=pool.Open()){var first=(points[0]+points[^1])*.5;curve.BeginFigure(new Point(first.X,first.Y),true,true);for(int n=0;n<points.Length;n++){var mid=(points[n]+points[(n+1)%points.Length])*.5;curve.QuadraticBezierTo(new Point(points[n].X,points[n].Y),new Point(mid.X,mid.Y),true,false);}}c.DrawGeometry(Brush(0x65451F,.25),null,pool);c.DrawGeometry(new RadialGradientBrush(((SolidColorBrush)Brush(0xD8C57F,.88)).Color,((SolidColorBrush)Brush(0x755324,.9)).Color){GradientOrigin=new Point(.4,.25)},null,pool);Line(c,Brush(0xFFF0C7,.65),Math.Max(.7,r*.036),new V(-r*1.05,-r*.3),new V(-r*.65,-r*.43),new V(-r*.15,-r*.4));}
  foreach(var drop in s.Drops){double progress=Math.Clamp(s.Age/drop.Flight,0,1);if(flying!=(progress<1))continue;double travel=1-Math.Pow(1-progress,2);var p=new V(drop.Offset.X*travel,drop.Offset.Y*travel-r*2.6*4*progress*(1-progress));double k=drop.Radius*(.3+Math.Min(1,progress*4)*.7);using var q=Transform(c,p.X,p.Y,Math.Atan2(drop.Offset.Y,drop.Offset.X));var blob=new StreamGeometry();using(var g=blob.Open()){g.BeginFigure(new Point(-k*(flying?3.4:1.9),0),true,true);g.BezierTo(new Point(-k*.6,-k*.4),new Point(k*.6,-k*1.4),new Point(k*(flying?1.8:1.15),0),true,false);g.BezierTo(new Point(k*1.3,k*1.5),new Point(-k*.7,k*.45),new Point(-k*(flying?3.4:1.9),0),true,false);}c.DrawGeometry(Gradient(0xE5D393,0x72511F),null,blob);Oval(c,-k*.1,-k*.55,k*.8,k*.25,Brush(0xFFF1C2,.8));}
 }
 public static void Draw(World w,DrawingContext c,bool pointer=true){c.DrawRectangle(Brushes.Transparent,null,new Rect(0,0,w.Width,w.Height));foreach(var s in new[]{Species.Roach,Species.Ant}){var p=w.Nest(s);Oval(c,p.X-24,p.Y-11,48,22,Brush(s==Species.Roach?0xCF9774u:0x99B299u,.25));Oval(c,p.X-16,p.Y-7,32,14,Brush(0x1F2D20,.7));}
  foreach(var f in w.Foods){using var t=Transform(c,f.P.X,f.P.Y,f.Angle);if(f.Original<=5)c.DrawGeometry(Brush(0xBE9450),null,Polygon(new V(-4,-3),new V(4,-2),new V(2,4),new V(-3,2)));else Food(c,f.Snack,f.Portions,f.Original,w.SnackScale(f.Snack));}
  foreach(var e in w.Eggs){int clipped=0;if(w.EggOccluded(e)){Geometry mask=new RectangleGeometry(new Rect(0,0,w.Width,w.Height));foreach(var place in w.Shelters)mask=new CombinedGeometry(GeometryCombineMode.Exclude,mask,new RectangleGeometry(new Rect(place.P.X-32,place.P.Y-24,64,48)));c.PushClip(mask);clipped=1;}using(var t=Transform(c,e.ShownPoint.X,e.ShownPoint.Y,e.Id%17*.19-1.4,sx:.15+.85*Math.Min(1,e.Emission*2)))Egg(c,e.Species);if(clipped>0)c.Pop();}foreach(var s in w.Splats)Juice(c,s);
  foreach(var b in w.Corpses){if(b.Species==Species.Ant&&CharacterLibrary.Shared.Enabled){using var avatarDead=Transform(c,b.P.X,b.P.Y,sx:w.Scale(b),sy:w.Scale(b),opacity:.64);CharacterArt.Draw(c,b,w.Clock,true);continue;}var s=w.Splats.FirstOrDefault(s=>s.BugId==b.Id&&s.Crushed);double press=s==null?0:Math.Max(0,1-s.Age/.22);using var t=Transform(c,b.P.X,b.P.Y,b.Angle,w.Scale(b)*(1+press*.28),w.Scale(b)*(.55-press*.28),s==null?.55:.78);Bug(c,b,0,true);}
  if(w.Archived>0)for(int n=0;n<6;n++)Oval(c,w.Width/2+n%3*5-8,w.Height-50+n/3*3,8,4,Brush(0x514638,.6));
  foreach(var cloud in w.Sprays)SprayMist(c,cloud);
  foreach(var b in w.Bugs.Where(b=>b.Flight!=null)){double k=w.Scale(b),lift=b.Flight!.Lift;Oval(c,b.P.X-30*k+lift*.35,b.P.Y+lift,60*k,16*k,Brush(0x000000,.09));}
  foreach(var b in w.Bugs.OrderBy(b=>b.Flight==null?0:1).ThenBy(b=>b.P.Y)){bool avatar=b.Species==Species.Ant&&CharacterLibrary.Shared.Enabled;double pulse=1+Math.Sin(Math.Clamp(b.BitePulse/.55,0,1)*Math.PI)*.07+(b.LayTime>0?Math.Sin(w.Clock*9)*.035:0);using var t=Transform(c,b.P.X+(b.Hit>0?Math.Sin(w.Clock*65+b.Id)*2:0),b.P.Y-(b.Id==w.Grabbed?12:0),avatar?0:b.Angle,w.Scale(b)*pulse,w.Scale(b)*pulse,.73+.27*b.Growth);if(avatar)CharacterArt.Draw(c,b,w.Clock);else Bug(c,b,b.Phase);if(b.Web>0)for(int n=-2;n<=2;n++)Line(c,Brush(0xF4F0E7,.7),.5,new V(-25,n*5-12),new V(27,n*5+12));if(b.Cargo>0&&!avatar)c.DrawGeometry(Brush(0xC89E58),null,Polygon(new V(b.Species==Species.Roach?37:15,-3),new V(b.Species==Species.Roach?45:19,0),new V(b.Species==Species.Roach?39:16,5)));}
  foreach(var v in w.Invaders){using var t=Transform(c,v.P.X,v.P.Y);Outsider(c,v);}
  foreach(var sweep in w.Sweeps){double t=Math.Clamp(sweep.Age/.65,0,1),ease=1-Math.Pow(1-t,3);foreach(var s in sweep.Stains){using var shift=Transform(c,sweep.P.X,sweep.P.Y,sx:1-ease*.6,sy:1-ease*.85,opacity:1-t);using var reverse=Transform(c,-sweep.P.X+ease*90,-sweep.P.Y-ease*35);Juice(c,s);}foreach(var b in sweep.Bodies){if(b.Species==Species.Ant&&CharacterLibrary.Shared.Enabled){using var avatarDead=Transform(c,b.P.X+ease*90,b.P.Y-ease*35,ease,w.Scale(b)*(1-ease*.75),w.Scale(b)*(1-ease*.75),(1-t)*.6);CharacterArt.Draw(c,b,w.Clock,true);continue;}using var q=Transform(c,b.P.X+ease*90,b.P.Y-ease*35,b.Angle+ease,w.Scale(b)*(1-ease*.75),w.Scale(b)*.55*(1-ease*.75),(1-t)*.55);Bug(c,b,0,true);}foreach(var e in sweep.Eggs){using var q=Transform(c,e.P.X+ease*90,e.P.Y-ease*35,opacity:1-t);Egg(c,e.Species);}foreach(var v in sweep.Outsiders){using var q=Transform(c,v.P.X+ease*90,v.P.Y-ease*35,opacity:1-t);Outsider(c,v);}using var broom=Transform(c,sweep.P.X-35+ease*85,sweep.P.Y,opacity:1-t*t);Broom(c,Math.Sin(t*Math.PI)*.7);}
  foreach(var f in w.Fights){if(CharacterArt.Fight(c,f,w))continue;double t=f.Age/.55;var p=f.From+(f.To-f.From)*.62;using var q=Transform(c,p.X,p.Y,Math.Atan2(f.To.Y-f.From.Y,f.To.X-f.From.X),f.Size,f.Size,1-t);if(f.Style==Attack.Web){for(int n=0;n<7;n++){double a=n*Math.PI*2/7;Line(c,Brush(0xF5F0E5),.8,V.Zero,new V(Math.Cos(a)*(12+t*24),Math.Sin(a)*(12+t*24)));}}else if(f.Style==Attack.Ram){for(int n=-2;n<=2;n++)Line(c,Brush(0xDDC28C),1.3,new V(-28,n*4),new V(9+t*12,n*6));}else{Line(c,Brush(0xFFF0C9),1.4,new V(-10,-12),new V(8,10));Line(c,Brush(0xFFF0C9),1.2,new V(-8,9),new V(12,-8));}for(int n=0;n<5;n++){double a=n*2.4;Oval(c,Math.Cos(a)*(8+t*20),Math.Sin(a)*(8+t*20),2,2,Brush(0xBAA078));}}
  foreach(var s in w.Splats)Juice(c,s,true);if(pointer&&w.Interactive){using var t=Transform(c,w.Pointer.X,w.Pointer.Y,opacity:.8);if(w.Tool==Tool.Spray){using var shift=Transform(c,-65,35);Aerosol(c);}else if(w.Tool==Tool.Shelter)c.DrawRectangle(null,new Pen(Art.Forest,1){DashStyle=DashStyles.Dash},new Rect(-32,-24,64,48));else if(w.Tool==Tool.Slipper)Slipper(c,.85);else if(w.Tool==Tool.Broom)Broom(c);else if(w.Tool==Tool.Food)Food(c,w.SelectedSnack,World.Servings[(int)w.SelectedSnack],World.Servings[(int)w.SelectedSnack],w.SnackScale(w.SelectedSnack));else if(w.Tool==Tool.RoachEgg||w.Tool==Tool.AntEgg)Egg(c,w.Tool==Tool.RoachEgg?Species.Roach:Species.Ant);}
  if(w.SlapAge<.38){using var t=Transform(c,w.Slap.X,w.Slap.Y,opacity:1-w.SlapAge/.38);Slipper(c,1.1);}
 }
}
public sealed class GameCanvas:FrameworkElement {
 public bool ShowPointer=true;public World World;public GameCanvas(World world){World=world;Focusable=true;ClipToBounds=true;RenderOptions.SetBitmapScalingMode(this,BitmapScalingMode.HighQuality);}
 protected override void OnRender(DrawingContext c)=>Art.Draw(World,c,ShowPointer);
}
